// ---- URL helpers: normalize -> absolute + cache-bust ----
const RUN_BUST = encodeURIComponent(order.runStamp || order.runId || Date.now());
function toAbsoluteAsset(u){
  const s = String(u || '').trim();
  if (!s) return '';
  if (/^https?:\/\//i.test(s)) return s;
  return `${backendUrl}/api/assets/${s.replace(/^\/+/, '')}`;
}
function withBust(u){
  if (!u) return '';
  const sep = u.includes('?') ? '&' : '?';
  return `${u}${sep}v=${RUN_BUST}`;
}
function norm(u){ return withBust(toAbsoluteAsset(u)); }

