// ----- robust value pickers -----
const firstStr = (...vals) => vals.find(v => typeof v === 'string' && v.trim().length) || '';

function deepFindUrl(obj, keyRegex) {
  try {
    const seen = new Set();
    const stack = [obj];
    while (stack.length) {
      const cur = stack.pop();
      if (!cur || typeof cur !== 'object' || seen.has(cur)) continue;
      seen.add(cur);
      for (const [k, v] of Object.entries(cur)) {
        if (keyRegex.test(String(k))) {
          if (typeof v === 'string' && v) return v;
          if (v && typeof v === 'object') {
            const hit = firstStr(v.imagePath, v.url, v.publicUrl, v.href);
            if (hit) return hit;
          }
        }
        if (v && typeof v === 'object') stack.push(v);
      }
    }
  } catch {}
  return '';
}

// fallback overlay finder (handles cases where renderCtx didn’t include keys)
function findOverlayUrl(i){
  if (i === 5  && p05OverlayUrl_fromCtx) return withBust(p05OverlayUrl_fromCtx);
  if (i === 12 && p12OverlayUrl_fromCtx) return withBust(p12OverlayUrl_fromCtx);

  const overlays = order.overlayImages || order.overlays || {};
  if (Array.isArray(overlays)) {
    const hit = overlays.find(o => Number(o.pageNumber) === i && (o.imagePath || o.url || o.publicUrl));
    if (hit) return withBust(toAbsoluteAsset(firstStr(hit.imagePath, hit.url, hit.publicUrl)));
  }
  if (overlays && typeof overlays === 'object') {
    if (i === 5) {
      const byKey = deepFindUrl(overlays, /footprint|p05|page.?5/i);
      if (byKey) return withBust(toAbsoluteAsset(byKey));
    }
    if (i === 12) {
      const byKey = deepFindUrl(overlays, /sparkle|glow|p12|page.?12/i);
      if (byKey) return withBust(toAbsoluteAsset(byKey));
    }
  }

  if (i === 5) {
    const guess = 'book-mvp-simple-adventure/overlays/footprints/footprints.png';
    return withBust(`${backendUrl}/api/assets/${guess}`);
  }
  return null;
}

