      `top:${toPx(OV14C.top)}`,
      `transform:translate(-50%,-100%) scaleX(${OV14C.flip})`,
      `width:${toPx(OV14C.w)}`,
      `z-index:11`
    ].join('; ') + ';';
  }
  const c = CHAR[n];
  if (!c) return '';
  return [
    `left:${toPx(c.left)}`,
    `top:${toPx(c.top)}`,
    `transform:translate(-50%,-100%) scaleX(${c.flip ?? 1})`,
