}

// ---- Animal sprites (robust key/nesting fallbacks) ----
function getAnimalSrc(kind){
  const a = order.animalImages || order.animal || {};
  const direct = kind === 'appears'
    ? firstStr(a.appears, a.appear, a.page13, a.p13, a.animalAppears, a.appearsImagePath, a.appearsUrl, a.imageAppears)
    : firstStr(a.flying, a.fly, a.page14, a.p14, a.animalFlying, a.flyingImagePath, a.flyingUrl, a.imageFlying);
  if (direct) return norm(direct);

  const regex = kind === 'appears' ? /appear|p13|page.?13/i : /flying|fly|p14|page.?14/i;
  const deep  = deepFindUrl(a, regex);
  if (deep) return norm(deep);

  // last resort: look in whole order payload
  const deepOrder = deepFindUrl(order, regex);
  return deepOrder ? norm(deepOrder) : '';
}

function animalHTML(i){
  const name = order.animalDisplayName || 'Animal';

  if (i === 13) {
    const src = getAnimalSrc('appears');
    if (!src) return `<div class="animal missing" data-missing="page13-appears"></div>`;
    const leftPx = 1191, topPx = 2104;

    // We want final rendered width ≈ 1100px on the 2625px canvas.
    const wLegacy = Math.round(1100 / (PX / BASE)); // == Math.round(1100 / SCALE)

    return `
      <div class="animal" style="
        left:${toPx(leftPx)};
        top:${toPx(topPx)};
        transform:translate(-50%,-100%);
        width:${toPx(wLegacy)};
        z-index:9;">
        <img class="sprite" src="${src}" alt="${name} Appears">
      </div>`;
  }

  if (i === 14) {
    const src = getAnimalSrc('flying');
    if (!src) return `<div class="animal missing" data-missing="page14-flying"></div>`;
    const left = toPx(1275), top = toPx(1964), w = toPx(1250);
    return `
      <div class="animal" style="
        left:${left};
        top:${top};
        transform:translate(-50%,-100%);
        width:${w};
        z-index:9;">
        <img class="sprite" src="${src}" alt="${name} Flying">
      </div>`;
  }
  return '';
}

// ---- text helpers ----
function prettifyText(raw){
  const withBr = String(raw || '').replace(/\n/g, '<br>');
  const parts = withBr.split('<br>');
  const widont = (seg) => seg.replace(/\s+([^\s<]{1,12})\s*$/u, '&nbsp;$1');
  return parts.map(s => widont(s.trim())).join('<br>');
}
function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, (m) => (
    {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[m]
  ));
}

