  ${dedText ? `<div class="dedication-wrap"><div class="dedication-text">${escapeHtml(dedText).replace(/\n/g,'<br>')}</div></div>` : ''}
</div>`;
  pages_html += p0;
  interiorPagesHTML.push(p0);
}

// pages 1..14
for (let i = 1; i <= 14; i++) {
  const bg   = findBg(i);
  const pose = findPose(i);
  const raw  = findRaw(i);
  const text = prettifyText(raw);
  const textBoxOverlay = withBust(getTextBoxOverlayUrl());

  // overlay with fallback discovery (guarantees a DOM element on p5)
  const overlayUrl = findOverlayUrl(i);

  // Text container (uniform, includes p5)
  const textBlock = `
  <div class="text-box" style="--overlay-url:url('${textBoxOverlay}')">
    <div class="text-content">${text || ''}</div>
