  ${overlayUrl ? `<div class="page-overlay" style="background-image:url('${overlayUrl}');"></div>` : ''}
  ${textBlock}
  ${pose ? `<div class="character" style="${charStyle(i)}"><img class="sprite" src="${pose.imagePath}" alt=""></div>` : ''}
  ${animalHTML(i)}
</div>`;
  pages_html += block;
  interiorPagesHTML.push(block);
}

