if (!order.characterImages || !Array.isArray(order.characterImages.poses)) {
  // Build poses from processedImages, ensuring correct pose-to-page mapping
  // processedImages come from 2B manifest with poseNumber 1-12
  // These should map directly to pages 1-12 (page 13 has animal only, page 14 has character + animal)
  const poses = processedImages
    .filter(pi => Number.isFinite(Number(pi.poseNumber)) && pi.poseNumber >= 1 && pi.poseNumber <= 12)
    .sort((a, b) => Number(a.poseNumber) - Number(b.poseNumber))
    .map(pi => {
