// Get order ready for book assembly (robust Webhook body handling)

// Webhook puts the real payload under .body; if not present, assume it's already flat
const input = $input.first().json;
const payload = input.body ?? input;

// Pull required fields from either flat or nested orderData
const amazonOrderId = payload.amazonOrderId ?? payload.orderData?.amazonOrderId ?? null;
const characterHash = payload.characterHash ?? payload.orderData?.characterHash ?? null;

// Optional sections
const characterSpecs = payload.characterSpecs ?? payload.orderData?.characterSpecs ?? {};
const bookSpecs      = payload.bookSpecs      ?? payload.orderData?.bookSpecs      ?? {};
const orderDetails   = payload.orderDetails   ?? payload.orderData?.orderDetails   ?? {};
// UPDATE: Removed hardcoded publicR2Url fallback - use backend proxy or signed URLs for external access
const publicR2Url    = payload.publicR2Url    ?? null;

// Processed images come in flat (2B sends them at top level)
const processedImages = payload.processedImages ?? [];

// Validate
if (!amazonOrderId || !characterHash) {
  throw new Error('Missing required order data: amazonOrderId or characterHash');
}
if (!Array.isArray(processedImages) || processedImages.length === 0) {
  throw new Error('No processed images received from Workflow 2B');
}

// Optional test gating (limit downstream page generations)
// testModePages: explicit numeric value OR default to 2 when testMode === true
const testMode = payload.testMode === true || payload.testMode === 'true';
const testModePages = Number(payload.testModePages ?? (testMode ? 2 : 0)) || 0;

// Normalize/initialize assembly state
const assemblingOrder = {
  status: 'book_assembly_in_progress',
  assemblyStartedAt: new Date().toISOString(),
  pagesGenerated: 0,
  totalPagesRequired: 15,
  assemblyProgress: 0,

  amazonOrderId,
  characterHash,
